909	// ShiftReport 按班次汇总完整事项、关闭情况、接班对象、每项交接当前结果与历次退回/补充说明。
910	// 进行中的班次展示当前事项；已结束班次展示结束时冻结的事项记录，
911	// 旧数据中缺少结束时记录的班次只展示当前事项并标明历史不完整。
912	func (svc *Service) ShiftReport(shiftID string) (ShiftReport, error) {
913		shiftID = clean(shiftID)
914		d := &svc.store.data
915		rep := ShiftReport{Results: map[string][]EntryView{}, LatestItems: map[string]Item{}}
916		sh, _ := findShift(d, shiftID)
917		if sh == nil {
918			return ShiftReport{}, fmt.Errorf("%w：班次 %s", ErrNotFound, shiftID)
919		}
920		rep.Shift = *sh
921	
922		for _, n := range d.Notes {
923			if n.ShiftA == sh.ID || n.ShiftB == sh.ID {
924				rep.OverlapNotes = append(rep.OverlapNotes, n)
925			}
926		}
927		sort.Slice(rep.OverlapNotes, func(i, j int) bool { return rep.OverlapNotes[i].ID < rep.OverlapNotes[j].ID })
928	
929		switch {
930		case !sh.Closed:
931			// 进行中的班次：事项可继续修改、关闭，展示当前信息。
932			rep.Items = currentItemsOfShift(d, sh.ID)
933		case sh.CloseRecord != nil:
934			// 已结束且有结束时记录：展示冻结的结束时信息，并对照最新状态。
935			rep.ItemsAtClose = true
936			rep.CloseItems = append([]CloseItemSnapshot(nil), sh.CloseRecord.Items...)
937			sort.Slice(rep.CloseItems, func(i, j int) bool { return rep.CloseItems[i].ItemID < rep.CloseItems[j].ItemID })
938			for _, s := range rep.CloseItems {
939				if it, _ := findItem(d, s.ItemID); it != nil {
940					rep.LatestItems[s.ItemID] = *it
941				}
942			}
943		default:
944			// 旧数据：结束时未留下记录，只能展示当前信息，不能宣称是结束时事实。
945			rep.HistoryIncomplete = true
946			rep.Items = currentItemsOfShift(d, sh.ID)
947		}
948		sort.Slice(rep.Items, func(i, j int) bool { return rep.Items[i].ID < rep.Items[j].ID })
949	
950		for i := range d.Handovers {
951			h := &d.Handovers[i]
952			involved := h.FromShiftID == sh.ID || h.ToShiftID == sh.ID
953			if !involved {
954				continue
955			}
956			if h.FromShiftID == sh.ID {
957				cp := *h
958				rep.Outgoing = &cp
959			}
960			if h.ToShiftID == sh.ID {
961				rep.Incoming = append(rep.Incoming, *h)
962			}
963			for j := range h.Entries {
964				rep.Results[h.Entries[j].ItemID] = append(rep.Results[h.Entries[j].ItemID], EntryView{
965					HandoverID: h.ID,
966					FromShift:  h.FromShiftID,
967					ToShift:    h.ToShiftID,
968					Entry:      h.Entries[j],
969				})
970			}
971		}
972		sort.Slice(rep.Incoming, func(i, j int) bool { return rep.Incoming[i].ID < rep.Incoming[j].ID })
973		for k := range rep.Results {
974			sort.Slice(rep.Results[k], func(i, j int) bool { return rep.Results[k][i].HandoverID < rep.Results[k][j].HandoverID })
975		}
976		return rep, nil
977	}
