		{"无法识别的接收方式", "交接 H001（S001 -> S002）接班班次接收：待定", false, receivedAttribution{}},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			got, ok := parseReceivedDetail(tc.detail)
